import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"復","description":"东坡易传 - 復","frontmatter":{"title":"復","description":"东坡易传 - 復"},"headers":[],"relativePath":"zh/classics/dongpo/025.md","filePath":"zh/classics/dongpo/025.md"}'),o={name:"zh/classics/dongpo/025.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><p>“復”，亨。出入無疾，朋來無咎。反覆其道，七日來複，利有攸往。</p><p>《彖》曰：“復，亨”。剛反動而以順行，是以“出入無疾”。 “朋來無咎，反覆其道，七日來複”。天行也。 “利有攸往”，剛長也；“復”，其見天地之心乎？</p><p>自“坤”爲“復”，謂之“入”；自“復”爲“乾”，謂之“出”。“疾”，病也。“坤”與初九爲“七”。見其意之所向謂之“心”，見其誠然謂之“情”。凡物之將亡而“復”者，非天地之所予者不能也。故陽之消也，五存而不足；及其長也，甫一而有餘。此豈人力也哉？《傳》曰：“天之所壞，不可支也；”其所支，亦不可壞也。違天不祥，必有大咎。</p><p>象曰：雷在地中，“復”；先王以至日閉關，商旅不行，後不省方。</p><p>“復”者，變易之際也。聖人居變易之際，靜以待其定，不可以有爲也，故“以至日閉關”明之，下至於“商旅不行”，上至於“後不省方”。</p><p>初九：不遠復，無祗悔。元吉。象曰：“不遠”之“復”，以修身也。</p><p>去其所居而復歸，亡其所有而復得，謂之“復”。必嘗去也而後有歸，必嘗亡也而後有得，無去則無歸，無亡則無得，是故聖人無復。初九未嘗見其有過也，然而始有復矣。孔子曰：“顏氏之子，其殆庶幾乎？有不善，未嘗不知；知之未嘗復行也。”</p><p>六二：休復，吉。象曰：“休復”之“吉”，以下仁也。</p><p>“休”，初九也。以陰居陰，不爭之至也，退而“休”之，使復者得信，謂之“休復”。</p><p>六三：頻復，厲，無咎。象曰：“頻復”之“厲”，義“無咎”也。</p><p>以陰居陽，力不得抗；而中不願，故頻於初九之復也。外順而內不平者，危則“無咎”。“頻”，蹙也。</p><p>六四：中行，獨復。象曰：“中行獨復”，以從道也。</p><p>“獨”，與初應。</p><p>六五：敦復，無悔。象曰：“敦復無悔”，中以自考也。</p><p>憂患未至而慮之，則“無悔”。六五，陰之方盛也；而內自度其終不足以抗初九，故因六四之獨復而附益之，以自託焉。</p><p>上六：迷復，兇，有災眚。用行師，終有大敗；以其國，君兇；至於十年不克徵。象曰：“迷復”之“兇”，反君道也。</p><p>乘極盛之末而用之不已，不知初九之已復也，謂之“迷復”。“災眚”者，在天之罰也①。初九之復，天也；衆莫不予，而己獨迷焉。用之於敵，則災其國；用之於國，則災其身。極盛必衰，驟勝故敗。在其終也，國敗君兇。至於十年而不復者，明其用民之過，而師競之甚也。</p><p>【校注】 ① 在天之罰：《蘇氏易傳》作“示天之罰”，亦通。</p>',19)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
